import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.x7b91k6X.js";const M=JSON.parse('{"title":"漫画 · 第 11 话 iOS 架构：MVC/MVVM/TCA 选型","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.11-ios-architecture.md","filePath":"comics/EP.11-ios-architecture.md","lastUpdated":1792677465000}'),i={name:"comics/EP.11-ios-architecture.md"};function l(d,e,n,s,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="漫画-·-第-11-话-ios-架构-mvc-mvvm-tca-选型" tabindex="-1">漫画 · 第 11 话 iOS 架构：MVC/MVVM/TCA 选型 <a class="header-anchor" href="#漫画-·-第-11-话-ios-架构-mvc-mvvm-tca-选型" aria-label="Permalink to &quot;漫画 · 第 11 话 iOS 架构：MVC/MVVM/TCA 选型&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../11-ios-architecture">11-ios-architecture.md</a> ｜ 原画：<a href="./EP.11-ios-architecture.svg">EP.11-ios-architecture.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>斯威芙蒂</strong>：一个 UserViewController 写了 1500 行，业务逻辑、网络、定位、UI 全混在一起，改一处崩三处。</li><li><strong>Runtime 长老</strong>：教她按「状态复杂度」选架构，不要盲目追新。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>MVC 本没错，错在把所有东西都塞进 Controller，变成 Massive View Controller。架构选型的核心维度是<strong>状态复杂度</strong>：简单静态页用 MVC 就够，中等业务用 MVVM + @Observable，多源状态/撤销重做/状态回放才上 TCA。主力方案是 MVVM，状态集中在 ViewModel，View 只做渲染。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>一个 VC 同时实现 <code>UITableViewDataSource</code>、<code>URLSessionDelegate</code>、<code>CLLocationManagerDelegate</code>，业务逻辑、网络请求、定位回调、UI 更新全在一个文件里。改一个网络回调，列表刷新逻辑也跟着动；加一个定位权限判断，三处 if 要同步改。<strong>职责不分离，复杂度指数级增长</strong>。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三轴对比：</p><table tabindex="0"><thead><tr><th>架构</th><th>适用场景</th><th>优点</th><th>缺点</th></tr></thead><tbody><tr><td><strong>MVC</strong></td><td>简单页面、原型</td><td>上手快、代码少</td><td>Controller 易胖，难测试</td></tr><tr><td><strong>MVVM</strong></td><td>主流业务页面</td><td>状态集中、可测试、与 SwiftUI 天然契合</td><td>需要约定数据流</td></tr><tr><td><strong>TCA</strong></td><td>复杂状态机、多源状态</td><td>单向数据流、可回放、可撤销重做</td><td>学习曲线陡、样板代码多</td></tr></tbody></table><p>选型决策树：<strong>状态只有一个来源 → MVC；状态来自多个输入但可集中管理 → MVVM；状态需要回溯/撤销/多组件协调 → TCA</strong>。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><ul><li><strong>简单页面（设置页、静态展示）</strong>：直接 MVC，不强行套架构，过度设计也是坏味道；</li><li><strong>业务页面（列表+详情+网络）</strong>：MVVM，<code>@Observable class ViewModel</code> 持有状态和业务方法，View 通过 <code>@State</code> 持有 ViewModel 实例，状态变化自动刷新；</li><li><strong>复杂场景（编辑器、工作流、多步表单）</strong>：TCA，State/Action/Reducer/Environment 四件套，状态可回放可测试。</li></ul><h2 id="runtime-长老划重点" tabindex="-1">Runtime 长老划重点 <a class="header-anchor" href="#runtime-长老划重点" aria-label="Permalink to &quot;Runtime 长老划重点&quot;">​</a></h2><ol><li>MVC 易胖、MVVM 平衡、TCA 严谨，按状态复杂度选型，不盲目追新。</li><li>主力 MVVM + @Observable，状态集中在 ViewModel，View 只做渲染。</li><li>架构目标是「可测、可维护」，不是「套名词」，简单页面别强行上 TCA。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：MVVM 里 ViewModel 应该持有 View 的引用吗？为什么？</p><p><strong>答</strong>：不应该。MVVM 的核心是「ViewModel 不依赖 View」，这样 ViewModel 可以脱离 UI 独立测试。数据流是单向的：View → ViewModel（用户操作调方法）→ ViewModel 更新状态 → View 观察状态自动刷新。如果 ViewModel 持有 View 引用，就形成了双向依赖，测试时必须 mock View，且容易出现循环引用。SwiftUI 里 View 通过 <code>@State</code>/<code>@StateObject</code> 持有 ViewModel，ViewModel 完全不知道 View 的存在。</p><h2 id="去实验室" tabindex="-1">去实验室 <a class="header-anchor" href="#去实验室" aria-label="Permalink to &quot;去实验室&quot;">​</a></h2><p>运行 <code>swift run ArchitecturePatterns</code>，对比同一需求的 MVC（反例）、MVVM（@Observable 状态机）、迷你 TCA 三种实现；阅读第 11 章的选型决策树和类型安全导航方案。</p><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>架构稳了，该给 App 加点「智能」了——图片分类、文字识别、本地推理。第 12 话《端上智能：Core ML 与设备侧 AI》，看模型怎么跑在用户手机上。</p>',24)])])}const u=t(i,[["render",l]]);export{M as __pageData,u as default};
